"""Build self-contained MAMORI presentation documents from verified project screenshots."""
from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'

def asset(name):
    return 'data:image/png;base64,' + base64.b64encode((DOCS / name).read_bytes()).decode()

images = {key: asset(name) for key, name in {
    'earthquake': 'v2-web-earthquake.png',
    'tsunami': 'v2-native-guide.png',
    'landslide': 'v2-native-landslide-zh.png',
    'volcano': 'v2-native-volcano-ja.png',
}.items()}

